"""Explicit editorial review of five criminal-investigation statutes.

Source bodies are checked separately; these are authored examples, not a
mechanical transformation of headings into alleged legal conclusions.
"""
import json
from pathlib import Path

P='https://www.planalto.gov.br/ccivil_03/'
STF_TEMP='https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=481715'
STF_DEL='https://portal.stf.jus.br/processos/detalhe.asp?incidente=4464179'
STJ_REG='https://processo.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisar&aplicacao=informativo&livre=%40cnot%3D014772'
STJ_904='https://scon.stj.jus.br/jurisprudencia/externo/informativo/?acao=pesquisar&aplicacao=informativo&livre=%40CNOT%3D022658'

# Summary, anchors, traps, case, changed fact, closed retrieval exercises, sources.
D={
'delegado':{
'art-1':('A lei disciplina a investigação conduzida pelo delegado. Seu âmbito não cria monopólio de toda investigação criminal: a ADI 5043 afastou essa leitura do art. 2º, §1º.', ['Objeto: investigação conduzida pelo delegado; não exclusividade de toda investigação.'], ['Distinguir polícia judiciária, procedimento investigatório e atribuições de outros órgãos.'], 'A polícia instaura inquérito para apurar um roubo e aplica as garantias desta lei.', 'O Ministério Público conduz investigação própria: a lei não a torna inválida apenas por não ser dirigida por delegado.', ['A lei torna toda investigação criminal exclusiva do delegado? Não; essa interpretação foi afastada na ADI 5043.', 'A lei disciplina a investigação conduzida pelo delegado? Sim; esse é seu objeto.'], [STF_DEL]),
'art-2':('As funções descritas são jurídicas, essenciais e exclusivas de Estado. O delegado apura circunstâncias, materialidade e autoria, requisita diligências e fundamenta o indiciamento. Avocação e redistribuição dependem de superior hierárquico e fundamento legal; remoção também exige motivação. Na ADI 5043, julgada em março de 2025, o STF afastou a leitura de exclusividade de toda investigação criminal.', ['Indiciamento: privativo do delegado, fundamentado, com análise técnico-jurídica.', 'Avocação/redistribuição: superior hierárquico, despacho fundamentado, interesse público ou falha regulamentar prejudicial à eficácia.', 'Remoção: ato fundamentado; §3º vetado não cria poder.'], ['Exclusivas de Estado não significa exclusivas de um único órgão investigador.', 'Requisição de dados não elimina reservas constitucionais e legais de jurisdição.', 'Não confunda indiciamento com denúncia do Ministério Público ou condenação judicial.'], 'O delegado indica os elementos de autoria e materialidade ao indiciar; a chefia só redistribui o caso com o fundamento exigido.', 'A chefia retira o caso sem justificar, ou se afirma que investigação própria do MP é sempre proibida: são leituras incompatíveis com as garantias legais e a ADI 5043.', ['Indiciamento e denúncia são o mesmo ato? Não; o primeiro é ato privativo do delegado e a denúncia pertence à persecução judicial.', 'A remoção do delegado pode ocorrer sem fundamentação? Não; o §5º exige ato fundamentado.', 'Exclusividade de Estado exclui necessariamente a investigação própria do MP? Não; a ADI 5043 afastou o monopólio da investigação criminal.'], [STF_DEL]),
'art-3':('O cargo exige bacharelado em Direito e recebe o tratamento protocolar indicado na lei. Igual tratamento protocolar não equipara cargos, atribuições, remunerações ou garantias constitucionais de carreiras distintas.', ['Requisito: bacharel em Direito.', 'Tratamento protocolar: magistrados, defensores, membros do MP e advogados.'], ['A lista inclui advogados; não se limita à magistratura.', 'O dispositivo não estabelece equiparação salarial.'], 'No ato oficial, o delegado recebe o tratamento protocolar previsto para os profissionais enumerados.', 'A questão conclui que isso garante o mesmo salário de magistrado: o artigo não contém essa regra.', ['O artigo cria equiparação salarial com magistrados? Não; trata de requisito e tratamento protocolar.', 'O cargo é privativo de bacharel em Direito? Sim; esse requisito está expresso.'], []),
'art-4':('A vigência original começou na publicação da lei, sem vacância fixada neste artigo. A consulta atual da compilação não reinicia esse marco e decisões posteriores exigem leitura própria.', ['Entrada em vigor: publicação.'], ['Data da assinatura e data da publicação são marcos distintos.'], 'A questão pergunta a vacância original: a lei não prevê espera de 45 dias neste dispositivo.', 'A pergunta trata da interpretação constitucional de 2025: consulte a ADI 5043, não uma nova vacância do art. 4º.', ['O art. 4º estabelece vacância de 45 dias? Não; prevê entrada em vigor na publicação.', 'Consultar a lei hoje reinicia sua vigência? Não; o marco original é a publicação.'], []),
},
'identificacao-criminal':{
'art-1':('A identificação civil dispensa, como regra, a criminal. A própria lei enumera exceções: apresentar documento não impede automaticamente os procedimentos quando uma dessas hipóteses estiver demonstrada.', ['Regra: civilmente identificado não se submete à identificação criminal.', 'Exceções: hipóteses legais, especialmente art. 3º.'], ['Não use a regra como proibição absoluta nem a exceção como autorização irrestrita.'], 'O investigado apresenta documento público idôneo e não há hipótese legal de exceção: aplica-se a proteção.', 'O documento tem indício de falsificação: deve-se examinar a exceção do art. 3º, I.', ['A apresentação de documento exclui todas as exceções legais? Não; o art. 1º ressalva os casos previstos na lei.', 'A identificação criminal é automática para todo investigado? Não; exige observar a regra e as hipóteses legais.'], []),
'art-2':('A lei admite carteira de identidade, trabalho, profissional, passaporte, identificação funcional e outro documento público capaz de identificar. Documentos militares são equiparados para essa finalidade.', ['Rol inclui passaporte e documento público apto.', 'Documento militar: equiparação expressa.'], ['Não restrinja a identificação civil apenas ao RG.', 'Documento privado qualquer não se torna documento público pela simples apresentação.'], 'O investigado apresenta passaporte suficiente para identificá-lo: é uma das formas legais.', 'Apresenta cartão privado sem aptidão e sem natureza pública: não se presume enquadramento no inciso VI.', ['Somente a carteira de identidade é admitida? Não; o artigo enumera outras formas.', 'Documentos de identificação militares são equiparados? Sim; o parágrafo único assim dispõe.'], []),
'art-3':('Mesmo com documento, podem justificar identificação criminal: rasura/falsificação; insuficiência; documentos conflitantes; essencialidade investigatória reconhecida judicialmente; registros de outros nomes; impossibilidade de identificação pelos caracteres do documento. A Lei 15.295/2025 acrescentou o recebimento judicial da denúncia por grave violência contra pessoa, crimes sexuais indicados, os arts. 240, 241 e 241-A a 241-C do ECA e organização criminosa do art. 2º da Lei 12.850 que use ou disponha de armas de fogo.', ['Inciso IV: decisão da autoridade judiciária; não basta vontade policial.', 'Inciso VII: recebimento da denúncia e crimes expressamente indicados.', 'Juntar cópias dos documentos, mesmo insuficientes.'], ['Lei 15.295: publicada em 22/12/2025, vacância de 30 dias; a mudança já está em vigor na conferência de outubro de 2026.', 'Não transforme o inciso VII em regra para toda denúncia ou toda organização.', 'A hipótese de flagrante com coleta genética está no art. 5º, §2º.'], 'O juiz recebe denúncia pelo art. 2º da Lei 12.850 e a organização dispõe de armas: examina-se a nova alínea d.', 'Sem armas e sem outra exceção legal demonstrada, a denúncia por esse crime não preenche, sozinha, a alínea d.', ['O inciso IV permite dispensar o despacho judicial sobre a essencialidade? Não; a decisão judicial integra a hipótese.', 'Qualquer denúncia recebida autoriza a nova hipótese do inciso VII? Não; o rol e suas condições devem ser observados.', 'Cópias de documentos considerados insuficientes devem ser juntadas? Sim; o parágrafo único exige a juntada.'], [P+'_ato2023-2026/2025/lei/l15295.htm']),
'art-4':('Quando a identificação criminal for necessária, a autoridade deve adotar providências para evitar constrangimento. A existência de fundamento para identificar não autoriza exposição vexatória ou tratamento humilhante.', ['Identificar com necessidade e respeito à pessoa.'], ['Necessidade do procedimento não elimina proteção à dignidade.'], 'A identificação é feita em ambiente e condições que preservam a pessoa, sem exibição desnecessária.', 'A equipe expõe o identificado para humilhá-lo: a autorização do procedimento não legitima o constrangimento.', ['O procedimento autorizado permite constrangimento desnecessário? Não; o artigo impõe providências para evitá-lo.', 'O dever recai sobre a autoridade encarregada? Sim; ela deve adotar as providências necessárias.'], []),
'art-5':('A identificação criminal inclui impressões digitais e fotografia, juntadas aos autos indicados. Pela Lei 15.295/2025, inclui coleta biológica para perfil genético nas hipóteses IV e VII do art. 3º e também no flagrante dos crimes do inciso VII.', ['Datiloscopia + fotografia; DNA nas hipóteses específicas.', 'Flagrante dos crimes do inciso VII: §2º próprio.'], ['Não ensine DNA obrigatório para qualquer identificação.', 'No flagrante previsto no §2º não se exige esperar o recebimento de denúncia para essa hipótese.', 'Mudança de 2025 com vacância de 30 dias, já transcorrida.'], 'Uma pessoa é presa em flagrante por crime sexual contra vulnerável: o §2º prevê identificação com coleta genética.', 'O fundamento é apenas rasura documental, sem incidência das hipóteses de coleta: rasura não torna, sozinha, todo DNA obrigatório pelo §1º.', ['A identificação criminal inclui datiloscopia e fotografia? Sim; ambas estão no caput.', 'O §2º exige esperar a denúncia no flagrante dos crimes referidos? Não; a própria hipótese é o flagrante.', 'DNA é obrigatório para toda identificação, independentemente da hipótese? Não; a lei estabelece hipóteses específicas.'], [P+'_ato2023-2026/2025/lei/l15295.htm']),
'art-5-a':('O banco de perfis genéticos é gerenciado por unidade oficial de perícia criminal. Os dados são sigilosos; a lei proíbe revelar traços somáticos ou comportamentais, com a exceção expressa da determinação genética de gênero. Coincidências devem constar de laudo assinado por perito oficial habilitado.', ['Unidade oficial de perícia; sigilo; laudo pericial.', 'Coincidência de perfil é elemento pericial, não condenação automática.'], ['Não confunda este banco com o multibiométrico do art. 7º-C.', 'Uso indevido pode gerar responsabilidade civil, penal e administrativa.'], 'Uma coincidência é encontrada e documentada em laudo oficial, a ser examinada com as demais provas.', 'Um servidor divulga dados genéticos para finalidade alheia à lei ou decisão judicial: o sigilo continua exigível.', ['A coincidência dispensa laudo de perito oficial? Não; o §3º exige esse laudo.', 'O banco pode revelar livremente traços comportamentais? Não; a lei contém proibição expressa.'], []),
'art-6':('Antes do trânsito em julgado da condenação, não se pode mencionar a identificação criminal em atestados de antecedentes ou informações não destinadas ao juízo criminal. A regra trata do destinatário e do marco processual.', ['Antes de condenação definitiva: vedação para atestados e informações externas ao juízo criminal.'], ['Identificação não equivale a condenação.', 'O dispositivo não proíbe encaminhar informação pertinente ao juízo criminal.'], 'Um atestado destinado a empregador não registra a identificação criminal de investigado sem condenação definitiva.', 'A informação é destinada ao juízo criminal: não se aplica indistintamente a mesma vedação externa.', ['Identificação criminal é prova de condenação definitiva? Não; são fatos distintos.', 'A regra proíbe indistintamente toda informação ao juízo criminal? Não; o texto diferencia esse destinatário.'], []),
'art-7':('Sem denúncia, com rejeição ou absolvição, o interessado pode requerer retirada da identificação fotográfica após arquivamento definitivo ou trânsito em julgado, apresentando prova de identificação civil.', ['Retirada de fotografia: requerimento + marco definitivo + prova civil.'], ['Não confunda retirada fotográfica com exclusão do perfil genético do art. 7º-A.', 'A mera notícia de investigação em curso não é o marco definitivo exigido.'], 'Após absolvição definitiva, o réu comprova identificação civil e requer a retirada da foto.', 'Pede exclusão de DNA: deve-se examinar o art. 7º-A, não substituir sua disciplina pela da fotografia.', ['Este artigo trata de retirada da fotografia? Sim; esse é seu objeto.', 'A retirada prevista independe de comprovação de identificação civil? Não; a prova é exigida.'], []),
'art-7-a':('Perfis genéticos são excluídos em caso de absolvição; em caso de condenação, a exclusão depende de requerimento após vinte anos do cumprimento da pena. Esse marco não é a coleta, o início da pena ou a data da sentença.', ['Absolvição; ou condenação + requerimento + 20 anos após cumprimento.'], ['Fotografia, perfil genético e dados multibiométricos têm regras distintas.', 'Não troque cumprimento da pena por data da coleta.'], 'O condenado terminou a pena: para esta hipótese de exclusão, conta-se o prazo legal a partir do cumprimento.', 'A amostra foi coletada há vinte anos, mas a pena terminou recentemente: a data da coleta não preenche o prazo.', ['Os vinte anos são contados da coleta? Não; o inciso II usa o cumprimento da pena.', 'Na hipótese de condenação, há exigência de requerimento? Sim; está expressa.'], []),
'art-7-b':('O perfil genético fica em banco sigiloso, conforme regulamentação do Executivo. Regulamentar a operação não torna os dados públicos nem permite uso irrestrito.', ['Banco sigiloso; regulamento do Poder Executivo.'], ['Ler em conjunto com os limites e responsabilidades do art. 5º-A.'], 'O órgão organiza o armazenamento conforme regulamento e protege o acesso.', 'Pretende divulgar a base ao público por existir regulamento: a regulamentação não afasta o sigilo.', ['O regulamento torna o banco público? Não; o artigo exige sigilo.', 'A regulamentação cabe ao Executivo? Sim; esse é o poder indicado.'], []),
'art-7-c':('O Banco Nacional Multibiométrico e de Impressões Digitais, no Ministério da Justiça e Segurança Pública, auxilia investigações federais, estaduais e distritais. Pode armazenar impressões e, quando possível, íris, face e voz. Integração exige acordo ou convênio; bancos civis, administrativos e eleitorais compartilham somente impressões digitais e informações necessárias à identificação do titular.', ['Dados sigilosos; comercialização total ou parcial proibida.', 'Coincidência: laudo de perito oficial habilitado.', 'Polícia e MP podem requerer acesso ao juiz em inquérito ou ação penal instaurados.', 'Registros de presos provisórios ou definitivos podem ser colhidos se não extraídos anteriormente.'], ['Interoperabilidade não autoriza copiar irrestritamente todo banco eleitoral.', 'Não confunda biometria de íris/voz com perfil genético.', 'Uso fora da lei ou decisão judicial gera responsabilidades nas três esferas.'], 'A unidade celebra convênio e limita o compartilhamento civil às impressões e informações identificadoras.', 'A proposta vende parte da base ou inclui indiscriminadamente voz do cadastro civil: não atende aos limites legais.', ['É permitida a venda de parte da base? Não; a proibição abrange comercialização total e parcial.', 'O compartilhamento civil autoriza todos os dados de íris, face e voz? Não; o §6º limita a impressões digitais e informações necessárias à identificação.', 'O banco serve somente a investigação federal? Não; abrange também investigações estaduais e distritais.'], []),
'art-8':('A Lei 12.037 entrou em vigor na publicação. Isso não elimina as vacâncias próprias das leis modificadoras: a Lei 15.295/2025 estabeleceu trinta dias após sua publicação oficial.', ['Vigência original imediata; alteração de 2025 com prazo próprio.'], ['Não aplique automaticamente a cláusula original a toda mudança posterior.'], 'Uma questão pergunta a regra original: entrada em vigor na publicação.', 'Pergunta a alteração genética de 2025: consulte os trinta dias do art. 3º da Lei 15.295.', ['Toda alteração posterior vigora imediatamente por causa deste art. 8º? Não; cada ato modificador pode ter prazo próprio.', 'A vigência original foi na publicação? Sim; o artigo assim prevê.'], [P+'_ato2023-2026/2025/lei/l15295.htm']),
'art-9':('A Lei 12.037 revogou expressamente a Lei 10.054/2000. Questões que atribuem vigência atual à lei anterior devem considerar essa revogação e as alterações posteriores da lei vigente.', ['Revogação expressa: Lei 10.054/2000.'], ['Não confunda lei revogada com revogação da própria Lei 12.037.'], 'O material recomenda usar a Lei 10.054 como disciplina vigente: é necessário corrigir a referência.', 'A pergunta é histórica, anterior à revogação: o marco temporal precisa ser respeitado.', ['O artigo revoga a própria Lei 12.037? Não; revoga a Lei 10.054/2000.', 'A lei anterior pode ser apresentada como vigente hoje sem ressalva? Não; a revogação é expressa.'], []),
},
'pf-interestadual':{
'art-1':('A PF pode investigar as infrações indicadas quando há repercussão interestadual ou internacional que exija repressão uniforme, sem excluir a responsabilidade dos demais órgãos de segurança. A lista abrange sequestros com motivação política/função da vítima, cartel, violações de direitos humanos de tratados, cargas, produtos medicinais, instituições financeiras, misoginia pela internet e transporte de valores. Outros casos exigem os pressupostos do caput e autorização ou determinação ministerial.', ['Caput: repercussão + necessidade de repressão uniforme; responsabilidades dos demais órgãos preservadas.', 'Cargas: transporte interestadual/internacional + indícios de grupo em mais de um Estado.', 'Instituições financeiras: indícios de associação em mais de um Estado.', 'Lei 14.967/2024: produtos controlados nas cargas e empresas de transporte de valores no inciso VIII.'], ['PF investigar não é regra automática de deslocamento de competência judicial.', 'Não elimine as condições específicas dos incisos IV e VI.', 'A referência antiga de cartel deve ser lida com a lei penal atual; não restaura incisos revogados da Lei 8.137.'], 'Há roubo de cargas interestaduais e indícios de grupo em dois Estados, com necessidade de repressão uniforme: a hipótese deve ser examinada pela PF sem excluir órgãos estaduais.', 'Um roubo isolado a instituição privada, sem indícios interestaduais nem os pressupostos gerais, não se enquadra automaticamente só por envolver dinheiro.', ['A atuação da PF exclui automaticamente as polícias estaduais? Não; o caput preserva suas responsabilidades.', 'O inciso VIII inclui empresas especializadas em transporte de valores? Sim; foi acrescentado pela Lei 14.967/2024.', 'A investigação de outros casos dispensa autorização/determinação ministerial? Não; o parágrafo único a exige, além dos pressupostos do caput.'], [P+'_ato2023-2026/2024/lei/l14967.htm']),
'art-2':('A vigência original foi fixada para a publicação. Alterações do rol, como a Lei 14.967/2024, precisam ser lidas no ato modificador e não retroagem automaticamente para tornar ilícita uma conduta anterior.', ['Vigência: publicação; atribuição investigatória não cria, sozinha, novo crime.'], ['Não confunda ampliar investigação com criar tipo penal ou pena.'], 'O aluno identifica a regra de vigência da Lei 10.446: publicação.', 'A questão atribui uma nova pena à ampliação do inciso VIII: esse artigo não cria tal sanção.', ['O art. 2º fixa vacância de 45 dias? Não; a vigência é na publicação.', 'A ampliação do rol investigatório cria, por si, uma nova pena? Não; atribuição investigatória e tipificação penal são distintas.'], []),
},
'temporaria':{
'art-1':('A leitura constitucional do STF nas ADIs 3360 e 4109 exige cinco requisitos cumulativos: imprescindibilidade concreta para o inquérito; fundadas razões de autoria/participação em crime do rol; fatos novos ou contemporâneos; adequação à gravidade concreta, circunstâncias e condições pessoais; insuficiência de cautelares alternativas. Falta de residência não autoriza, sozinha, a prisão. O rol não admite ampliação por analogia.', ['Memória I-A-C-A-S: imprescindibilidade, autoria, contemporaneidade, adequação, subsidiariedade.', 'Cinco requisitos cumulativos; prisão para averiguações proibida.'], ['Não trate os incisos I, II e III como alternativas independentes.', 'O texto conserva remissões históricas a tipos e diplomas alterados/revogados; consultar CP e legislação atual, sem inventar novo crime no rol.', 'Prisão cautelar não é pena antecipada.'], 'No inquérito por roubo, há elementos atuais de participação e demonstração concreta de necessidade; o juiz também examina adequação e insuficiência das alternativas.', 'O único motivo é morar na rua: não atende aos requisitos constitucionais e não legitima prisão para averiguações.', ['A falta de residência fixa basta, sozinha? Não; o STF exige cinco requisitos cumulativos.', 'O rol pode ser ampliado por analogia? Não; a interpretação fixada proíbe essa ampliação.', 'Fatos novos ou contemporâneos e insuficiência de alternativas devem ser examinados? Sim; integram os requisitos cumulativos.'], [STF_TEMP]),
'art-2':('Só o juiz decreta temporária, provocado por representação policial ou requerimento do MP. O prazo geral é cinco dias, prorrogável por igual período diante de extrema e comprovada necessidade. A decisão é fundamentada em até 24 horas; na representação policial, ouve-se antes o MP. O mandado informa duração e dia de soltura, e o dia de cumprimento entra na contagem.', ['Prazo geral 5 + 5; hediondos/equiparados: consultar 30 + 30 do art. 2º, §4º, da Lei 8.072.', 'Somente executar após mandado, em duas vias, com ciência dos direitos.', 'Término: soltar imediatamente sem nova ordem, salvo comunicação prévia de prorrogação ou preventiva.'], ['Juiz pode determinar apresentação/exame de ofício pelo §3º, mas isso não autoriza decretar a prisão de ofício.', 'Prorrogação não é automática.', 'Lei 13.869/2019 alterou soltura e acrescentou conteúdo do mandado e dia inicial da contagem.'], 'O mandado é cumprido na segunda-feira e o prazo termina sem comunicação de prorrogação ou preventiva: a custódia deve liberar imediatamente no marco legal.', 'A autoridade espera novo alvará só porque o prazo terminou: o §7º dispensa nova ordem nessa hipótese.', ['O juiz pode decretar temporária de ofício com base no §3º? Não; esse parágrafo trata de apresentação, informações e exame.', 'O dia do cumprimento do mandado entra na contagem? Sim; o §8º o inclui.', 'A soltura por fim do prazo depende sempre de nova ordem? Não; o §7º exige liberação, ressalvadas as comunicações previstas.'], [P+'leis/l8072.htm',P+'_ato2019-2022/2019/lei/l13869.htm']),
'art-3':('Presos temporários devem permanecer separados dos demais detentos. É regra de custódia, não autorização para tratamento degradante ou restrição de direitos sem base legal.', ['Separação obrigatória dos demais detentos.'], ['Não confundir separação com pena de isolamento ou regime disciplinar.'], 'A unidade organiza a custódia do preso temporário separadamente dos demais detentos.', 'A equipe chama essa separação de punição disciplinar: a natureza da regra é de custódia, não de sanção.', ['A separação é facultativa pelo artigo? Não; é obrigatória.', 'Essa regra constitui pena disciplinar de isolamento? Não; é exigência de custódia.'], []),
'art-4':('O artigo acrescentou historicamente crime à Lei 4.898/1965, que foi revogada pela Lei 13.869/2019. Não ensine aquela alínea como tipo penal vigente. A disciplina atual inclui o art. 12, parágrafo único, IV, da Lei 13.869, que deve ser lido com seus elementos e a finalidade específica do art. 1º, §1º.', ['Lei 4.898: revogada; consultar tipo atual de abuso e seus requisitos.'], ['Não concluir que qualquer atraso, sem examinar dolo e finalidade legal, configura automaticamente abuso de autoridade.', 'A revogação do tipo antigo não elimina o dever de soltura do art. 2º, §7º.'], 'Um material de hoje aplica a antiga alínea i da Lei 4.898 como vigente: a referência penal precisa ser atualizada.', 'O caso trata de descumprimento atual de ordem de liberdade: examinam-se a Lei 13.869 e o contexto, não se reaplica automaticamente a lei revogada.', ['A antiga Lei 4.898 continua vigente por estar transcrita neste artigo? Não; foi revogada pela Lei 13.869.', 'A análise de abuso atual dispensa os requisitos subjetivos da Lei 13.869? Não; eles devem ser examinados.'], [P+'_ato2019-2022/2019/lei/l13869.htm']),
'art-5':('Todas as comarcas e seções judiciárias devem ter plantão permanente de 24 horas do Judiciário e do MP para apreciar pedidos de prisão temporária. Plantão assegura apreciação, mas não dispensa os requisitos da medida.', ['Plantão permanente: Judiciário e MP, 24 horas.'], ['Disponibilidade de plantão não torna automática a prisão.'], 'O pedido chega de madrugada e pode ser apreciado no plantão dos órgãos indicados.', 'O requerente sustenta que a urgência dispensa fundamentação: os requisitos continuam necessários.', ['O plantão é apenas do Judiciário? Não; o artigo inclui o Ministério Público.', 'O plantão dispensa os critérios do art. 1º? Não; facilita a apreciação, sem remover requisitos.'], []),
'art-6':('A Lei 7.960 entrou em vigor na publicação. A cláusula original não afasta os marcos próprios de alterações posteriores nem a interpretação constitucional fixada pelo STF.', ['Vigência original na publicação.'], ['Distinguir marco original, alteração legislativa e interpretação judicial.'], 'A prova pergunta a vigência original: publicação.', 'A prova pergunta os critérios constitucionais atuais: usa-se também o julgamento de 2022, não só os incisos isolados.', ['O art. 6º fixa espera de 45 dias? Não; a vigência é na publicação.', 'A cláusula de vigência dispensa leitura da jurisprudência constitucional? Não; são aspectos diferentes.'], []),
'art-7':('A cláusula revoga disposições incompatíveis, sem listar a revogação de todo o sistema processual penal. Ela não substitui a pesquisa de atos posteriores e dos dispositivos vigentes.', ['Revogação por incompatibilidade, não de todo o CPP.'], ['Não use a fórmula geral para presumir revogação de uma norma compatível.'], 'Ao comparar normas, o aluno identifica conflito concreto antes de afirmar revogação.', 'As regras são compatíveis: o texto geral não determina que uma delas seja descartada sem análise.', ['A cláusula revoga integralmente o CPP? Não; refere-se às disposições em contrário.', 'É necessário verificar incompatibilidade ao aplicar a cláusula? Sim; não se presume revogação indiscriminada.'], []),
},
'tortura':{
'art-1':('A tortura abrange obtenção de informação/confissão, provocação de crime e discriminação racial/religiosa com violência ou grave ameaça; castigo/prevenção exige guarda, poder ou autoridade e sofrimento intenso. A Lei Barbara Penna, 15.410/2026, acrescentou sofrimento intenso reiterado de mulher em violência doméstica/familiar, em vigor desde a publicação em 21/05/2026. A pena básica é reclusão de 2 a 8 anos; omissão com dever de evitar/apurar recebe detenção de 1 a 4.', ['Lesão grave/gravíssima: reclusão 4–10; morte: 8–16.', 'Aumento 1/6 a 1/3: agente público; vítimas enumeradas; sequestro.', 'Perda de cargo/função/emprego e interdição pelo dobro da pena; inafiançabilidade e vedação de graça/anistia.', 'Texto do §7º indica fechado, mas STJ aplica individualização pelo CP e Súmulas 440/STJ e 719/STF.', 'Informativo STJ 904, outubro/2026: majorante de agente público é compatível com tortura de pessoa presa, sem bis in idem automático.'], ['Não confundir detenção da omissão com reclusão dos tipos ativos.', 'O novo inciso III exige reiteração; não classificar toda discussão doméstica como tortura.', 'Na literalidade da majorante, a idade é maior de 60, não substituir silenciosamente por 60 ou mais.', 'Crime inafiançável não significa automaticamente imprescritível.', 'Regime inicial fechado não é obrigatório pela mera gravidade abstrata.'], 'O agressor submete reiteradamente a mulher a sofrimento intenso em contexto doméstico: examinam-se os elementos do inciso III e as demais infrações cabíveis. Em outro caso, agente público impõe sofrimento ilegal a preso: a majorante pode incidir com o §1º, conforme STJ 904.', 'Quem tinha dever de evitar ou apurar apenas se omite: examina-se o §2º, com pena distinta. Ao fixar regime, o juiz individualiza e não aplica fechado automaticamente só pelo nome do crime.', ['A omissão do §2º tem pena de reclusão de 2 a 8 anos? Não; sua pena é detenção de 1 a 4.', 'O inciso III exige sofrimento intenso reiterado no contexto doméstico/familiar? Sim; são elementos da redação de 2026.', 'Toda condenação por tortura exige automaticamente regime inicial fechado? Não; a jurisprudência exige individualização.', 'A majorante de agente público é sempre incompatível com tortura de pessoa presa? Não; o STJ 904 reconheceu compatibilidade porque as circunstâncias são distintas.'], [P+'_ato2023-2026/2026/lei/l15410.htm',STJ_REG,STJ_904]),
'art-2':('A lei também se aplica a crime cometido fora do Brasil quando a vítima é brasileira ou o agente se encontra em local sob jurisdição brasileira. O artigo usa alternativas, e não exige simultaneamente nacionalidade brasileira da vítima e presença do autor.', ['Memória: vítima brasileira OU agente sob jurisdição brasileira.'], ['Não trocar a conjunção ou por e.', 'Aplicação da lei não dispensa garantias processuais e análise dos fatos.'], 'A vítima é brasileira e o crime ocorreu no exterior: o artigo contém hipótese de aplicação.', 'A vítima é estrangeira, mas o agente se encontra sob jurisdição brasileira: a outra hipótese deve ser examinada.', ['As duas condições precisam ocorrer juntas? Não; o texto usa alternativas.', 'O artigo se limita a fatos ocorridos dentro do território nacional? Não; prevê aplicação também fora dele.'], []),
'art-3':('A Lei 9.455 entrou em vigor na publicação. A alteração de 2026 também adotou publicação como marco próprio; para a nova modalidade penal, deve-se respeitar a irretroatividade da lei penal mais gravosa.', ['Vigência original: publicação; nova modalidade: publicação da Lei 15.410 em 21/05/2026.'], ['Não usar uma nova incriminação mais gravosa para fatos anteriores ao marco legal.'], 'A prova pergunta quando a lei original iniciou vigência: na publicação.', 'O fato é anterior à nova modalidade de 2026: não se aplica retroativamente a nova incriminação mais gravosa; examina-se a legislação aplicável ao fato.', ['O art. 3º fixa vacância de 45 dias? Não; usa a publicação.', 'A nova modalidade pode retroagir automaticamente para prejudicar o acusado? Não; deve-se respeitar a irretroatividade penal mais gravosa.'], [P+'_ato2023-2026/2026/lei/l15410.htm']),
'art-4':('A Lei de Tortura revogou o art. 233 do ECA, antigo dispositivo sobre tortura. Não revogou todo o Estatuto nem o art. 232, que trata de vexame ou constrangimento de criança/adolescente sob autoridade, guarda ou vigilância.', ['Revogado: ECA art. 233; não confundir com art. 232.'], ['Nem todo constrangimento é automaticamente tortura: examinar elementos de cada tipo.'], 'O material cita o art. 233 do ECA como crime vigente: deve ser corrigido pela revogação expressa.', 'A conduta envolve vexame no art. 232: esse artigo não foi revogado pelo art. 4º da Lei de Tortura.', ['Foi revogado todo o ECA? Não; a revogação é do art. 233.', 'O artigo revogado foi o 232? Não; foi o 233.'], [P+'leis/l8069.htm']),
}}

for slug, articles in D.items():
    units={k:dict(simples=s,pontos=p,atencao=a,exemplo=e+' Variação: '+v,prova=q,termos=[],remissoes=r) for k,(s,p,a,e,v,q,r) in articles.items()}
    Path(f'scripts/explicacoes/{slug}-revisao-aplicada-2026-10-11.json').write_text(json.dumps(dict(course_slug=slug,units=units),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(sum(map(len,D.values())), 'explicitly authored articles')
